-- ── hand-amended: the blind RMA CHECKs (migration SQL only) ──────────────
DO $$
BEGIN
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.return_authorizations'::regclass AND conname = 'return_authorizations_origin_check') THEN
		ALTER TABLE "return_authorizations" ADD CONSTRAINT "return_authorizations_origin_check" CHECK (
			"origin" IN ('authorized','blind')
		) NOT VALID;
	END IF;
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.return_authorizations'::regclass AND conname = 'return_authorizations_review_status_check') THEN
		ALTER TABLE "return_authorizations" ADD CONSTRAINT "return_authorizations_review_status_check" CHECK (
			"review_status" IS NULL OR "review_status" IN ('pending','accepted','rejected')
		) NOT VALID;
	END IF;
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.return_authorizations'::regclass AND conname = 'return_authorizations_match_kind_check') THEN
		ALTER TABLE "return_authorizations" ADD CONSTRAINT "return_authorizations_match_kind_check" CHECK (
			"match_kind" IS NULL OR "match_kind" IN ('awb','order-reference')
		) NOT VALID;
	END IF;
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.return_authorizations'::regclass AND conname = 'return_authorizations_review_reason_code_check') THEN
		ALTER TABLE "return_authorizations" ADD CONSTRAINT "return_authorizations_review_reason_code_check" CHECK (
			"review_reason_code" IS NULL OR "review_reason_code" IN ('mis-scanned','not-our-goods','duplicate','other')
		) NOT VALID;
	END IF;
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.return_authorizations'::regclass AND conname = 'return_authorizations_parcel_reference_length') THEN
		ALTER TABLE "return_authorizations" ADD CONSTRAINT "return_authorizations_parcel_reference_length" CHECK (
			"parcel_reference" IS NULL OR (char_length("parcel_reference") BETWEEN 1 AND 64 AND "parcel_reference" = btrim("parcel_reference"))
		) NOT VALID;
	END IF;
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.return_authorizations'::regclass AND conname = 'return_authorizations_review_note_length') THEN
		ALTER TABLE "return_authorizations" ADD CONSTRAINT "return_authorizations_review_note_length" CHECK (
			"review_note" IS NULL OR (char_length("review_note") BETWEEN 1 AND 200 AND "review_note" = btrim("review_note"))
		) NOT VALID;
	END IF;
	-- An authorized RMA: its order, its dispatch instant, no blind column. A
	-- blind RMA: a review status and the prompt flag; the order and its
	-- instant together; an order only once accepted.
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.return_authorizations'::regclass AND conname = 'return_authorizations_origin_shape') THEN
		ALTER TABLE "return_authorizations" ADD CONSTRAINT "return_authorizations_origin_shape" CHECK (
			(
				"origin" = 'authorized'
				AND "order_id" IS NOT NULL AND "order_dispatched_at" IS NOT NULL
				AND "review_status" IS NULL AND "parcel_reference" IS NULL AND "suggested_order_id" IS NULL
				AND "match_kind" IS NULL AND "client_prompted" IS NULL AND "reviewed_by" IS NULL
				AND "reviewed_at" IS NULL AND "review_reason_code" IS NULL AND "review_note" IS NULL
			)
			OR (
				"origin" = 'blind'
				AND "review_status" IS NOT NULL AND "client_prompted" IS NOT NULL
				AND ("order_id" IS NULL) = ("order_dispatched_at" IS NULL)
				AND ("order_id" IS NULL OR "review_status" = 'accepted')
			)
		) NOT VALID;
	END IF;
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'public.return_authorizations'::regclass AND conname = 'return_authorizations_review_shape') THEN
		ALTER TABLE "return_authorizations" ADD CONSTRAINT "return_authorizations_review_shape" CHECK (
			("reviewed_by" IS NULL) = ("reviewed_at" IS NULL)
			AND coalesce("review_status" IN ('accepted','rejected'), false) = ("reviewed_by" IS NOT NULL)
			AND coalesce("review_status" = 'rejected', false) = ("review_reason_code" IS NOT NULL)
			AND ("review_reason_code" IS NULL OR "review_reason_code" <> 'other' OR "review_note" IS NOT NULL)
			AND ("match_kind" IS NULL) = ("suggested_order_id" IS NULL)
		) NOT VALID;
	END IF;
END $$;
--> statement-breakpoint
-- ── the proof on data and the post-migration assertion (the 0111 model) ──
-- (a) the nine CHECKs are present and NOT VALID. (b) every existing RMA is
-- `authorized`, and no existing row violates any new CHECK (counted
-- explicitly — NOT VALID does not check them). (c) every accepted shape
-- inserts — an authorized RMA, a blind RMA in each review state, with and
-- without an order and a suggestion, an `unannounced` unlinked line — and is
-- rolled back by a sentinel exception, so a CHECK that refused everything
-- fails the migration. (d) each refused shape runs in its own subtransaction
-- and must be refused BY ITS NAMED CONSTRAINT (Postgres evaluates CHECKs in
-- name order; each probe violates only its target, or one that sorts first is
-- expected). Made-up uuids.
DO $$
DECLARE
	t uuid := gen_random_uuid();
	o uuid := gen_random_uuid();
	u uuid := gen_random_uuid();
	refused_by text;
	expected text;
	probe text;
	n int;
	total int;
BEGIN
	-- (a)
	SELECT count(*) INTO n
	  FROM pg_constraint
	 WHERE conrelid = 'public.return_authorizations'::regclass
	   AND conname IN ('return_authorizations_origin_check', 'return_authorizations_review_status_check',
	                   'return_authorizations_match_kind_check', 'return_authorizations_review_reason_code_check',
	                   'return_authorizations_parcel_reference_length', 'return_authorizations_review_note_length',
	                   'return_authorizations_origin_shape', 'return_authorizations_review_shape')
	   AND contype = 'c'
	   AND NOT convalidated;
	IF n <> 8 THEN
		RAISE EXCEPTION 'migration 0112: expected the eight return_authorizations CHECKs present and NOT VALID, found % so.', n;
	END IF;
	SELECT count(*) INTO n
	  FROM pg_constraint
	 WHERE conrelid = 'public.return_authorization_lines'::regclass
	   AND conname = 'return_authorization_lines_reason_code_check'
	   AND contype = 'c'
	   AND NOT convalidated;
	IF n <> 1 THEN
		RAISE EXCEPTION 'migration 0112: expected return_authorization_lines_reason_code_check re-added NOT VALID, found % so.', n;
	END IF;
	-- (b)
	SELECT count(*) INTO total FROM "return_authorizations";
	SELECT count(*) INTO n FROM "return_authorizations" WHERE "origin" = 'authorized';
	IF n <> total THEN
		RAISE EXCEPTION 'migration 0112: % of % existing RMA(s) are not authorized.', total - n, total;
	END IF;
	SELECT count(*) INTO n FROM "return_authorizations"
	 WHERE NOT (
		"origin" = 'authorized'
		AND "order_id" IS NOT NULL AND "order_dispatched_at" IS NOT NULL
		AND "review_status" IS NULL AND "parcel_reference" IS NULL AND "suggested_order_id" IS NULL
		AND "match_kind" IS NULL AND "client_prompted" IS NULL AND "reviewed_by" IS NULL
		AND "reviewed_at" IS NULL AND "review_reason_code" IS NULL AND "review_note" IS NULL
	 );
	IF n <> 0 THEN
		RAISE EXCEPTION 'migration 0112: % existing RMA(s) violate the authorized shape.', n;
	END IF;
	SELECT count(*) INTO n FROM "return_authorization_lines"
	 WHERE "order_line_id" IS NULL
	    OR "reason_code" NOT IN ('damaged','defective','wrong-item','not-as-described','changed-mind','other');
	IF n <> 0 THEN
		RAISE EXCEPTION 'migration 0112: % existing RMA line(s) are unlinked or carry an unknown reason.', n;
	END IF;
	-- (c)
	BEGIN
		INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","order_id","code","status","order_dispatched_at","created_by",
			"origin","review_status","parcel_reference","suggested_order_id","match_kind","client_prompted","reviewed_by","reviewed_at","review_reason_code","review_note")
		VALUES
			-- an authorized RMA (every pre-4-7b row)
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), o, 'P-1', 'open', now(), u,
			 'authorized', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
			-- blind, pending, no reference, no suggestion
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), NULL, 'P-2', 'received', NULL, u,
			 'blind', 'pending', NULL, NULL, NULL, false, NULL, NULL, NULL, NULL),
			-- blind, pending, a reference and an AWB suggestion, client prompted
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), NULL, 'P-3', 'received', NULL, u,
			 'blind', 'pending', 'AWB123', o, 'awb', true, NULL, NULL, NULL, NULL),
			-- blind, accepted with an order
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), o, 'P-4', 'received', now(), u,
			 'blind', 'accepted', '1042-BO1', o, 'order-reference', false, u, now(), NULL, NULL),
			-- blind, accepted with no order
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), NULL, 'P-5', 'received', NULL, u,
			 'blind', 'accepted', NULL, NULL, NULL, false, u, now(), NULL, NULL),
			-- blind, rejected, a reason without a note
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), NULL, 'P-6', 'received', NULL, u,
			 'blind', 'rejected', NULL, NULL, NULL, false, u, now(), 'mis-scanned', NULL),
			-- blind, rejected `other` with its note
			(gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), NULL, 'P-7', 'received', NULL, u,
			 'blind', 'rejected', NULL, NULL, NULL, true, u, now(), 'other', 'wrong building');
		INSERT INTO "return_authorization_lines" ("id","tenant_id","rma_id","line_no","order_line_id","sku_id","authorized_qty","received_qty","reason_code")
		VALUES
			(gen_random_uuid(), t, gen_random_uuid(), 1, NULL, gen_random_uuid(), 3000, 3000, 'unannounced'),
			(gen_random_uuid(), t, gen_random_uuid(), 1, gen_random_uuid(), gen_random_uuid(), 1000, 0, 'damaged');
		RAISE EXCEPTION USING ERRCODE = 'P0112', MESSAGE = 'rollback the accepted probes';
	EXCEPTION
		WHEN check_violation OR not_null_violation OR unique_violation THEN
			RAISE EXCEPTION 'migration 0112: an accepted shape was refused (%).', SQLERRM;
		WHEN SQLSTATE 'P0112' THEN
			NULL;
	END;
	-- (d)
	FOREACH probe IN ARRAY ARRAY[
		'origin unknown', 'authorized with a review', 'authorized without its order', 'blind without a review status',
		'blind without the prompt flag', 'blind pending with an order', 'blind order without its instant',
		'match kind unknown', 'match kind without a suggestion', 'suggestion without a match kind',
		'reference blank', 'reference untrimmed', 'reference too long', 'review status unknown',
		'accepted without a reviewer', 'pending with a reviewer', 'reviewer without an instant',
		'rejected without a reason', 'accepted with a reason', 'reason unknown', 'other without a note',
		'note blank', 'line reason unknown'
	] LOOP
		refused_by := NULL;
		expected := CASE
			WHEN probe = 'origin unknown' THEN 'return_authorizations_origin_check'
			WHEN probe IN ('authorized with a review', 'authorized without its order', 'blind without a review status',
			               'blind without the prompt flag', 'blind pending with an order', 'blind order without its instant')
				THEN 'return_authorizations_origin_shape'
			WHEN probe = 'match kind unknown' THEN 'return_authorizations_match_kind_check'
			WHEN probe IN ('reference blank', 'reference untrimmed', 'reference too long') THEN 'return_authorizations_parcel_reference_length'
			WHEN probe = 'review status unknown' THEN 'return_authorizations_review_status_check'
			WHEN probe = 'reason unknown' THEN 'return_authorizations_review_reason_code_check'
			WHEN probe = 'note blank' THEN 'return_authorizations_review_note_length'
			WHEN probe = 'line reason unknown' THEN 'return_authorization_lines_reason_code_check'
			ELSE 'return_authorizations_review_shape'
		END;
		BEGIN
			CASE probe
				WHEN 'origin unknown' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","order_id","code","status","order_dispatched_at","created_by","origin")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), o, 'R-1', 'open', now(), u, 'mystery');
				WHEN 'authorized with a review' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","order_id","code","status","order_dispatched_at","created_by","origin","review_status")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), o, 'R-1', 'open', now(), u, 'authorized', 'pending');
				WHEN 'authorized without its order' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","order_id","code","status","order_dispatched_at","created_by","origin")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), NULL, 'R-1', 'open', NULL, u, 'authorized');
				WHEN 'blind without a review status' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","client_prompted")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', false);
				WHEN 'blind without the prompt flag' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'pending');
				WHEN 'blind pending with an order' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","order_id","code","status","order_dispatched_at","created_by","origin","review_status","client_prompted")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), o, 'R-1', 'received', now(), u, 'blind', 'pending', false);
				WHEN 'blind order without its instant' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","order_id","code","status","created_by","origin","review_status","client_prompted","reviewed_by","reviewed_at")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), o, 'R-1', 'received', u, 'blind', 'accepted', false, u, now());
				WHEN 'match kind unknown' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted","suggested_order_id","match_kind")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'pending', false, o, 'guess');
				WHEN 'match kind without a suggestion' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted","match_kind")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'pending', false, 'awb');
				WHEN 'suggestion without a match kind' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted","suggested_order_id")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'pending', false, o);
				WHEN 'reference blank' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted","parcel_reference")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'pending', false, '');
				WHEN 'reference untrimmed' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted","parcel_reference")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'pending', false, ' AWB1');
				WHEN 'reference too long' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted","parcel_reference")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'pending', false, repeat('x', 65));
				WHEN 'review status unknown' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'maybe', false);
				WHEN 'accepted without a reviewer' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'accepted', false);
				WHEN 'pending with a reviewer' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted","reviewed_by","reviewed_at")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'pending', false, u, now());
				WHEN 'reviewer without an instant' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted","reviewed_by")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'accepted', false, u);
				WHEN 'rejected without a reason' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted","reviewed_by","reviewed_at")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'rejected', false, u, now());
				WHEN 'accepted with a reason' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted","reviewed_by","reviewed_at","review_reason_code")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'accepted', false, u, now(), 'duplicate');
				WHEN 'reason unknown' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted","reviewed_by","reviewed_at","review_reason_code")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'rejected', false, u, now(), 'bored');
				WHEN 'other without a note' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted","reviewed_by","reviewed_at","review_reason_code")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'rejected', false, u, now(), 'other');
				WHEN 'note blank' THEN
					INSERT INTO "return_authorizations" ("id","tenant_id","client_id","warehouse_id","code","status","created_by","origin","review_status","client_prompted","reviewed_by","reviewed_at","review_reason_code","review_note")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), gen_random_uuid(), 'R-1', 'received', u, 'blind', 'rejected', false, u, now(), 'other', '');
				WHEN 'line reason unknown' THEN
					INSERT INTO "return_authorization_lines" ("id","tenant_id","rma_id","line_no","order_line_id","sku_id","authorized_qty","received_qty","reason_code")
					VALUES (gen_random_uuid(), t, gen_random_uuid(), 1, NULL, gen_random_uuid(), 1000, 0, 'lost');
			END CASE;
		EXCEPTION
			WHEN check_violation THEN
				GET STACKED DIAGNOSTICS refused_by = CONSTRAINT_NAME;
		END;
		IF refused_by IS DISTINCT FROM expected THEN
			RAISE EXCEPTION 'migration 0112: probe "%" was refused by % (expected %).', probe, coalesce(refused_by, 'nothing'), expected;
		END IF;
	END LOOP;
	IF EXISTS (SELECT 1 FROM "return_authorizations" WHERE "tenant_id" = t) OR EXISTS (SELECT 1 FROM "return_authorization_lines" WHERE "tenant_id" = t) THEN
		RAISE EXCEPTION 'migration 0112: a probe row survived.';
	END IF;
END $$;
